using System;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
[InitializeOnLoad] public static class StorybookRebirthSequenceAuthoring{
 public const string Path="Assets/DarkFairytale/UI/RebirthSequence/StorybookRebirthSequence.prefab",Art="Assets/DarkFairytale/UI/RebirthSequence/Art/ForestThreshold.png",Out="output/rebirth-sequence/";
 static StorybookRebirthSequenceAuthoring(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Out+"build.request"))return;File.Delete(Out+"build.request");try{Build();File.WriteAllText(Out+"build.txt","PASS");}catch(Exception e){File.WriteAllText(Out+"build.txt",e.ToString());}};}
 static RectTransform Rect(Transform p,string name,float w,float h){var r=(RectTransform)new GameObject(name,typeof(RectTransform)).transform;r.SetParent(p,false);r.anchorMin=r.anchorMax=r.pivot=Vector2.one*.5f;r.sizeDelta=new Vector2(w,h);return r;}
 static void Full(RectTransform r){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;}
 static Image Image(RectTransform r,Color color){var i=r.gameObject.AddComponent<Image>();i.color=color;i.raycastTarget=false;return i;}
 static Text Text(Transform p,string name,string content,float y,int size){var r=Rect(p,name,940,100);r.anchoredPosition=new Vector2(0,y);var t=r.gameObject.AddComponent<Text>();t.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/DarkFairytale/UI/CursedStorybook/Fonts/NotoSerifCJKsc-Black.otf");t.fontSize=size;t.text=content;t.alignment=TextAnchor.MiddleCenter;t.color=new Color(.97f,.90f,.76f);t.raycastTarget=false;var shadow=r.gameObject.AddComponent<Shadow>();shadow.effectColor=Color.black;shadow.effectDistance=new Vector2(2,-3);return t;}
 public static void Build(){AssetDatabase.ImportAsset(Art);var importer=(TextureImporter)AssetImporter.GetAtPath(Art);importer.textureType=TextureImporterType.Sprite;importer.maxTextureSize=2048;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();if(!File.Exists(Path)){var root=new GameObject("StorybookRebirthSequence",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster),typeof(StorybookRebirthSequence));try{root.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;root.GetComponent<Canvas>().sortingOrder=29000;var ui=root.GetComponent<StorybookRebirthSequence>();ui.pageSound=root.AddComponent<AudioSource>();ui.pageSound.playOnAwake=false;ui.pageSound.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/StorybookIntro/Prologue/SinglePageTurn.wav");var back=Rect(root.transform,"FullScreenInk",1,1);Full(back);Image(back,new Color(.025f,.020f,.02f)).raycastTarget=true;ui.composition=Rect(root.transform,"PortraitComposition",1080,1920);ui.art=Rect(ui.composition,"ForestThreshold",1080,1920);Image(ui.art,Color.white).sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Art);
 var glow=Rect(ui.composition,"DawnLight",1080,1920);ui.warmth=Image(glow,new Color(1,.85f,.6f,0));ui.leaves=new RectTransform[12];for(int i=0;i<12;i++){var leaf=Rect(ui.composition,"DriftingPage"+i,14+i%3*5,22+i%4*4);leaf.anchoredPosition=new Vector2((i%2==0?-1:1)*(170+i*19),-600+i*105);Image(leaf,new Color(.80f,.72f,.56f)).sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/DarkFairytale/UI/Chest/Sprites/BlankPaper.asset");leaf.gameObject.AddComponent<CanvasGroup>().alpha=0;ui.leaves[i]=leaf;}
 var texts=Rect(ui.composition,"LiveTitles",1080,1920);ui.titleGroup=texts.gameObject.AddComponent<CanvasGroup>();ui.titleGroup.alpha=0;ui.title=Text(texts,"Title","旧页终章",670,60);ui.subtitle=Text(texts,"Subtitle","",580,28);ui.subjectNumber=Text(texts,"SubjectNumber","No. 001",-840,22);
 var curtain=Rect(root.transform,"OpeningInk",1,1);Full(curtain);Image(curtain,Color.black);ui.curtain=curtain.gameObject.AddComponent<CanvasGroup>();ui.curtain.alpha=1;root.SetActive(false);PrefabUtility.SaveAsPrefabAsset(root,Path);}finally{UnityEngine.Object.DestroyImmediate(root);}}
 var saved=PrefabUtility.LoadPrefabContents(Path);try{saved.GetComponent<Canvas>().sortingOrder=29000;var composition=saved.GetComponent<StorybookRebirthSequence>().composition;if(!composition.GetComponent<RectMask2D>())composition.gameObject.AddComponent<RectMask2D>();PrefabUtility.SaveAsPrefabAsset(saved,Path);}finally{PrefabUtility.UnloadPrefabContents(saved);}
 const string package="Assets/Prefab/Addressable Prefabs/RebirthPackage.prefab";var host=PrefabUtility.LoadPrefabContents(package);try{var rp=host.GetComponent<RebirthPackage>();if(!rp.sequence){if(rp.cutsceneObj)UnityEngine.Object.DestroyImmediate(rp.cutsceneObj);if(rp.dummy)rp.dummy.gameObject.SetActive(false);if(rp.firstCamera)rp.firstCamera.SetActive(false);var sequence=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Path),host.transform);rp.sequence=sequence.GetComponent<StorybookRebirthSequence>();rp.cutsceneObj=sequence;PrefabUtility.SaveAsPrefabAsset(host,package);}}finally{PrefabUtility.UnloadPrefabContents(host);}AssetDatabase.SaveAssets();}
}
